// Откройте Add: измените умножение на params.step — результат изменится во всех вызовах.
// Один исходник, независимое value у каждого подключения.
const component = {
  name: "Counter",
  parameters: {
    type: "object",
    properties: {
      initial: { type: "number", default: 0, label: "Начальное значение" },
      storySource: {
        type: "boolean",
        default: false,
        label: "Менять источник постоянной привязки явно",
      },
      step: { type: "number", default: 1, label: "Множитель изменения" },
    },
  },
  state: {
    type: "object",
    properties: { value: { type: "number", default: 0, label: "Текущее значение" } },
  },
  stateFromParameters: { value: "initial" },
  signals: {
    changed: {
      name: "Значение изменилось",
      payloadSchema: { type: "object", properties: { value: { type: "number" } } },
    },
  },
  methods: {
    add: {
      name: "Добавить",
      parameters: {
        type: "object",
        properties: { amount: { type: "number", default: 1, label: "Количество" } },
      },
      result: { type: "number" },
      async run({ args, params, state, engine }) {
        const next = state.value + args.amount * params.step;
        if (params.storySource) await engine.writeBinding("value", next);
        else state.value = next;
        await engine.emit("changed", { value: state.value });
        return state.value;
      },
    },
    read: {
      name: "Прочитать",
      result: { type: "number" },
      run({ state }) {
        return state.value;
      },
    },
    multiply: {
      name: "Умножить",
      parameters: {
        type: "object",
        properties: { factor: { type: "number", default: 2, label: "Множитель" } },
      },
      result: { type: "number" },
      async run({ args, params, state, engine }) {
        const next = state.value * args.factor;
        if (params.storySource) await engine.writeBinding("value", next);
        else state.value = next;
        await engine.emit("changed", { value: state.value });
        return state.value;
      },
    },
  },
};

// Упражнение: замените base * multiplier на base * multiplier + 5.
// Получатель — явная ссылка на Counter, одинаковая логика для очков, монет и отношения.
// Добавьте новый метод bonus с вызовом engine.invoke(refs.counter, "add", {amount: ...}).
const component = {
  name: "Reward",
  parameters: {
    type: "object",
    properties: {
      base: { type: "number", default: 1, label: "Базовая награда" },
      multiplier: { type: "number", default: 1, label: "Множитель награды" },
    },
  },
  references: {
    type: "object",
    properties: {
      counter: { type: "reference", referenceType: "mechanic", label: "Куда начислять · Counter" },
    },
  },
  state: {
    type: "object",
    properties: { awards: { type: "integer", default: 0, label: "Выдано наград" } },
  },
  signals: {
    awarded: {
      name: "Награда выдана",
      payloadSchema: {
        type: "object",
        properties: { amount: { type: "number" }, value: { type: "number" } },
      },
    },
  },
  methods: {
    award: {
      name: "Начислить награду",
      parameters: {
        type: "object",
        properties: { factor: { type: "number", default: 1, label: "Разовый множитель" } },
      },
      result: { type: "number" },
      async run({ args, params, refs, state, engine }) {
        const amount = params.base * params.multiplier * args.factor;
        const value = await engine.invoke(refs.counter, "add", { amount });
        state.awards += 1;
        await engine.emit("awarded", { amount, value });
        return value;
      },
    },
  },
};

// Timer — сериализуемый native handle этого компонента. Tick вызывает тот же Reward,
// что кнопка. Disable/Stop удаляет только его таймер; восстановление сохраняет remaining.
const component = {
  name: "PeriodicReward",
  parameters: {
    type: "object",
    properties: {
      seconds: { type: "number", min: 0.05, default: 1, label: "Интервал" },
      initialRate: { type: "number", default: 1, label: "Начальная скорость" },
      autoStart: { type: "boolean", default: true, label: "Запустить после подготовки" },
    },
  },
  state: {
    type: "object",
    properties: {
      rate: { type: "number", default: 1, label: "Награда за тик" },
      running: { type: "boolean", default: false, label: "Таймер включён" },
    },
  },
  stateFromParameters: { rate: "initialRate", running: "autoStart" },
  references: {
    type: "object",
    properties: {
      reward: { type: "reference", referenceType: "mechanic", label: "Общая награда" },
    },
  },
  lifecycle: { enable: "prepare", disable: "stop" },
  subscriptions: [{ id: "own-timer", signal: "timer", match: "timer", methodId: "tick" }],
  methods: {
    prepare: {
      name: "Подготовить таймер",
      async run({ state, self, engine }) {
        if (state.running) await engine.invoke(self, "start", {});
      },
    },
    start: {
      name: "Запустить таймер",
      async run({ params, state, owner, engine }) {
        state.running = true;
        await engine.operation("sacura.timer.start", {
          owner,
          name: "reward",
          seconds: params.seconds,
          repeat: true,
          restart: false,
        });
      },
    },
    stop: {
      name: "Остановить таймер",
      async run({ state, owner, engine }) {
        state.running = false;
        await engine.operation("sacura.timer.stop", { owner, name: "reward" });
      },
    },
    tick: {
      name: "Выдать периодическую награду",
      async run({ state, refs, engine }) {
        if (state.running) await engine.invoke(refs.reward, "award", { factor: state.rate });
      },
    },
    upgrade: {
      name: "Улучшить",
      result: { type: "number" },
      run({ state }) {
        state.rate += 1;
        return state.rate;
      },
    },
  },
};
